  for(const mode of ['linear','soft','firm']){
   editor.newDocument({width:64,height:64});const layer=editor.document.layers.add(new PaintLayer());layer.strokes.add(new BrushStroke({points:[{x:20,y:20,pressure:.5}],size:40,hardness:1,color:'#ff0000',pressureOpacity:true,pressureCurve:PressureCurve[mode]()}));
   const native=await createImageBitmap(await editor.exportPng()),svg=(await editor.export({format:'svg'})).blob,url=URL.createObjectURL(svg),image=new Image(),canvas=document.createElement('canvas');canvas.width=canvas.height=64;
   try{image.src=url;await image.decode();const context=canvas.getContext('2d');context.drawImage(native,0,0);const reference=[20,28,35].map(x=>[...context.getImageData(x,20,1,1).data]);context.clearRect(0,0,64,64);context.drawImage(image,0,0);results.push({mode,reference,svg:[20,28,35].map(x=>[...context.getImageData(x,20,1,1).data])});}finally{native.close();URL.revokeObjectURL(url);canvas.width=canvas.height=0;}
  }return results;
