 await page.getByRole('button',{name:'Brush tool (B)',exact:true}).click();await page.getByRole('button',{name:'Pressure response…',exact:true}).click();await page.getByLabel('Response preset',{exact:true}).selectOption('firm');await page.setViewportSize({width:390,height:844});await page.screenshot({path:'/tmp/canoli-pressure-curve-narrow.png'});
